drop database if exists issue_27398;
create database issue_27398;
use issue_27398;

create table nullable_index_alignment (
    id int primary key,
    n int null
);

select count(*) from nullable_index_alignment;
select count(*) from nullable_index_alignment where n is null;

create index idx_n on nullable_index_alignment(n);

update nullable_index_alignment
set n = coalesce(n, 0)
where id % 4 = 0;

select count(*) from nullable_index_alignment where n = 0;
select count(*) from nullable_index_alignment where n + 0 = 0;
select count(*) from nullable_index_alignment
where not(
    n <=> case
        when id % 7 = 0 and id % 4 = 0 then 0
        when id % 7 = 0 then null
        else id % 19 - 9
    end
);

delete from nullable_index_alignment where id % 17 = 0;

select count(*) from nullable_index_alignment;
select count(*) from nullable_index_alignment where id % 17 = 0;

drop database issue_27398;
